import React, { useState } from 'react';
import axios from 'axios';

const ScanForm: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [status, setStatus] = useState<'idle' | 'loading' | 'success' | 'error'>('idle');
  const [message, setMessage] = useState('');

  const resetForm = () => {
    setFile(null);
    setStatus('idle');
    setMessage('');
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selected = e.target.files?.[0] || null;

    if (selected && !['application/pdf', 'image/png', 'image/jpeg'].includes(selected.type)) {
      setStatus('error');
      setMessage('Tipul de fișier nu este acceptat.');
      return;
    }

    if (selected && selected.size > 5 * 1024 * 1024) { // 5MB limit
      setStatus('error');
      setMessage('Fișierul este prea mare. Limită: 5MB.');
      return;
    }

    setFile(selected);
    setStatus('idle');
    setMessage('');
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!file) return;

    const formData = new FormData();
    formData.append('file', file);

    try {
      setStatus('loading');
      const res = await axios.post('/api/scan', formData, {
        headers: {
          'Content-Type': 'multipart/form-data',
        },
      });
      setStatus('success');
      setMessage(res.data.message || 'Scanare finalizată cu succes!');
    } catch (err: any) {
      setStatus('error');
      setMessage(err.response?.data?.error || 'Eroare la scanare.');
    }
  };

  return (
    <div className="card mt-8 animate-fadeIn">
      <h3 className="text-xl font-bold mb-4">Încarcă un fișier pentru scanare</h3>
      <form onSubmit={handleSubmit}>
        <div className="form-group">
          <label htmlFor="file" className="form-label">Fișier</label>
          <input
            type="file"
            id="file"
            className="form-input"
            aria-label="Selectează fișier pentru scanare"
            onChange={handleFileChange}
          />
        </div>
        <div className="flex items-center">
          <button
            type="submit"
            className="btn"
            disabled={status === 'loading' || !file}
            aria-busy={status === 'loading'}
          >
            {status === 'loading' ? 'Scanare...' : 'Încarcă fișier'}
          </button>
          <button
            type="button"
            className="btn-outline ml-2"
            onClick={resetForm}
          >
            Reset
          </button>
        </div>
        {message && (
          <p
            className={`mt-4 text-sm ${
              status === 'success' ? 'text-green-300' : 'text-red-300'
            }`}
            role="alert"
          >
            {message}
          </p>
        )}
      </form>
    </div>
  );
};

export default ScanForm;

